type N = {v:number,l:N|null,r:N|null};
function tree(a:(number|null)[]):N|null { if(!a.length||a[0]===null)return null; const root:N={v:a[0],l:null,r:null};const q:N[]=[root];let j=1;for(let i=0;i<q.length&&j<a.length;i++){for(const side of ['l','r'] as const){const v=a[j++];if(v!==null&&v!==undefined){const n:N={v,l:null,r:null};q[i][side]=n;q.push(n);}}}return root;}
export function buildTree(preorder: number[], inorder: number[]): (number|null)[] {
let index=0;const positions=new Map(inorder.map((v,i)=>[v,i]));function build(l:number,r:number):N|null{if(l>r)return null;const v=preorder[index++],mid=positions.get(v)!;return {v,l:build(l,mid-1),r:build(mid+1,r)};}const root=build(0,inorder.length-1);if(!root)return [];const out:(number|null)[]=[],q:(N|null)[]=[root];for(let i=0;i<q.length;i++){const n=q[i];out.push(n?n.v:null);if(n)q.push(n.l,n.r);}while(out[out.length-1]===null)out.pop();return out;
}
